<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\Holder\UserConsentPurposesGrantedAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentPurposesGrantedAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserConsentPurposesGrantedAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isGranted returns null on a freshly created holder.
     */
    public function testGrantedNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesGrantedAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isGrantedAssigned());
        $this->assertNull($holder->isGranted());
    }
}
class ImplWithUserConsentPurposesGrantedAttributeHolderUnitTest
{
    use UserConsentPurposesGrantedAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedGrantedRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultGranted();
    }
}
